<?php require 'includes/db.php';require 'includes/auth.php';if(logged_in()){header('Location:index.php');exit;}$error='';if($_SERVER['REQUEST_METHOD']==='POST'){$name=trim($_POST['name']??'');$email=strtolower(trim($_POST['email']??''));$pass=$_POST['password']??'';$confirm=$_POST['confirm_password']??'';if(strlen($name)<2)$error='Enter your name.';elseif(!filter_var($email,FILTER_VALIDATE_EMAIL))$error='Enter a valid email.';elseif(strlen($pass)<6)$error='Password must contain at least 6 characters.';elseif($pass!==$confirm)$error='Passwords do not match.';else{try{$s=$pdo->prepare("INSERT INTO users(name,email,password_hash) VALUES(?,?,?)");$s->execute([$name,$email,password_hash($pass,PASSWORD_DEFAULT)]);$_SESSION['user_id']=$pdo->lastInsertId();ensure_default_categories($pdo);header('Location:index.php');exit;}catch(Exception $e){$error='An account with that email already exists.';}}}?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Create Account</title><link rel="stylesheet" href="assets/auth.css"></head><body><div class="auth"><div class="logo">₹</div><h1>Create account</h1><p>Start tracking your money privately</p><?php if($error):?><div class="error"><?=h($error)?></div><?php endif;?><form method="post"><label>Name<input name="name" required></label><label>Email<input type="email" name="email" required></label><label>Password<input type="password" name="password" minlength="6" required></label><label>Confirm Password<input type="password" name="confirm_password" minlength="6" required></label><button>Create Account</button></form><p>Already have an account? <a href="login.php">Login</a></p></div></body></html>